/* Carrier Slot History table */
CREATE TABLE MRASCRRSHS
(
    CRR_ID                      VARCHAR2(20)     DEFAULT(' ')    NOT NULL,
    SLOT_NO                     NUMBER(6)        DEFAULT(0)      NOT NULL,
    HIST_SEQ                    NUMBER(10)       DEFAULT(0)      NOT NULL,
    TRAN_TIME                   VARCHAR2(14)     DEFAULT(' ')    NOT NULL,
    /* Transaction Code */
    TRAN_CODE                   VARCHAR2(12)     DEFAULT(' ')    NOT NULL,
    CRR_HIST_SEQ                NUMBER(10)       DEFAULT(0)      NOT NULL,
    CRR_SLOT_HIST_SEQ           NUMBER(10)       DEFAULT(0)      NOT NULL,
    SUBLOT_ID                   VARCHAR2(30)     DEFAULT(' ')    NOT NULL,
    SUBLOT_HIST_SEQ             NUMBER(10)       DEFAULT(0)      NOT NULL,
    OLD_CRR_HIST_SEQ            NUMBER(10)       DEFAULT(0)      NOT NULL,
    OLD_SUBLOT_ID               VARCHAR2(30)     DEFAULT(' ')    NOT NULL,
    OLD_SUBLOT_HIST_SEQ         NUMBER(10)       DEFAULT(0)      NOT NULL,
    TRAN_USER_ID                VARCHAR2(20)     DEFAULT(' ')    NOT NULL
) TABLESPACE HISTORY_DATA_TS;

ALTER TABLE MRASCRRSHS
ADD CONSTRAINT MRASCRRSHS_PK PRIMARY KEY
(
    CRR_ID,
    SLOT_NO,
    HIST_SEQ
) USING INDEX TABLESPACE HISTORY_IDX_TS;

CREATE INDEX MRASCRRSHS_IDX_1 ON MRASCRRSHS
(
    CRR_ID, 
    CRR_SLOT_HIST_SEQ
) TABLESPACE MESPLUS_IDX_TS;

CREATE TABLE TRASCRRSHS
(
    CRR_ID                      VARCHAR2(20)     DEFAULT(' ')    NOT NULL,
    SLOT_NO                     NUMBER(6)        DEFAULT(0)      NOT NULL,
    HIST_SEQ                    NUMBER(10)       DEFAULT(0)      NOT NULL,
    TRAN_TIME                   VARCHAR2(14)     DEFAULT(' ')    NOT NULL,
    /* Transaction Code */
    TRAN_CODE                   VARCHAR2(12)     DEFAULT(' ')    NOT NULL,
    CRR_HIST_SEQ                NUMBER(10)       DEFAULT(0)      NOT NULL,
    CRR_SLOT_HIST_SEQ           NUMBER(10)       DEFAULT(0)      NOT NULL,
    SUBLOT_ID                   VARCHAR2(30)     DEFAULT(' ')    NOT NULL,
    SUBLOT_HIST_SEQ             NUMBER(10)       DEFAULT(0)      NOT NULL,
    OLD_CRR_HIST_SEQ            NUMBER(10)       DEFAULT(0)      NOT NULL,
    OLD_SUBLOT_ID               VARCHAR2(30)     DEFAULT(' ')    NOT NULL,
    OLD_SUBLOT_HIST_SEQ         NUMBER(10)       DEFAULT(0)      NOT NULL,
    TRAN_USER_ID                VARCHAR2(20)     DEFAULT(' ')    NOT NULL
) TABLESPACE HISTORY_DATA_TS;

DECLARE
    V_PREV_SUBLOT_ID    VARCHAR2(30);
    V_PREV_CRR_ID       VARCHAR2(20);
    V_PREV_SLOT_NO      NUMBER(6);
    V_PREV_CRR_HIST_SEQ NUMBER(6);
    V_CRR_HIST_SEQ      NUMBER(6);

    V_SLOT_HIST_SEQ     NUMBER(6);
    V_OLD_CRR_HIST_SEQ  NUMBER(6);
    V_OLD_SUBLOT_HIST_SEQ  NUMBER(6);
    V_OLD_SUBLOT_ID     VARCHAR2(30);
    V_PREV_TRAN_CODE    VARCHAR2(12);
    V_TRAN_CODE         VARCHAR2(12);

    V_PREV_TRAN_TIME    VARCHAR2(14);
    V_CRR_SLOT_HIST_SEQ NUMBER(6);
BEGIN

    V_PREV_SUBLOT_ID := ' ';
    V_PREV_CRR_ID := ' ';
    V_PREV_SLOT_NO := 0;
    V_PREV_CRR_HIST_SEQ := 0;

    FOR SUBLOT IN (
        SELECT * 
        FROM MWIPSLTHIS 
        WHERE HIST_DEL_FLAG = ' '
        ORDER BY SUBLOT_ID, HIST_SEQ
    )
    LOOP
    
        IF V_PREV_SUBLOT_ID != SUBLOT.SUBLOT_ID THEN
            V_PREV_SUBLOT_ID := SUBLOT.SUBLOT_ID;
            V_PREV_CRR_ID := ' ';
            V_PREV_SLOT_NO := 0;
            V_PREV_CRR_HIST_SEQ := 0;
        END IF;
        
        V_CRR_HIST_SEQ := 0;
       
        IF SUBLOT.CRR_ID != ' ' THEN
        
            BEGIN
                SELECT /*+ INDEX_DESC(CHIS MRASCRRHIS_PK ) */ HIST_SEQ 
                INTO V_CRR_HIST_SEQ
                FROM MRASCRRHIS CHIS
                WHERE CRR_ID = SUBLOT.CRR_ID 
                    AND LOT_ID = SUBLOT.LOT_ID
                    AND LOT_HIST_SEQ <= SUBLOT.LOT_HIST_SEQ
                    AND ROWNUM = 1;
                
                EXCEPTION
                    WHEN NO_DATA_FOUND THEN
                        V_CRR_HIST_SEQ := 0;
            END;

        END IF;
       
        IF V_PREV_CRR_ID != SUBLOT.CRR_ID THEN
        
            IF V_PREV_CRR_ID = ' ' AND SUBLOT.CRR_ID != ' ' THEN
            
                    SUBLOT.CRR_ID, SUBLOT.SLOT_NO, 0, SUBLOT.TRAN_TIME, 'ATTACH', V_CRR_HIST_SEQ, 0, 
                    SUBLOT.SUBLOT_ID, SUBLOT.HIST_SEQ, 0, ' ', 0, SUBLOT.TRAN_USER_ID);
                
            ELSIF V_PREV_CRR_ID != ' ' AND SUBLOT.CRR_ID = ' ' THEN
            
                    V_PREV_CRR_ID, V_PREV_SLOT_NO, 0, SUBLOT.TRAN_TIME, 'DETACH', V_PREV_CRR_HIST_SEQ, 0, 
                    SUBLOT.SUBLOT_ID, SUBLOT.HIST_SEQ, 0, ' ', 0, SUBLOT.TRAN_USER_ID);
            
            ELSIF V_PREV_CRR_ID != ' ' AND SUBLOT.CRR_ID != ' ' THEN

                    V_PREV_CRR_ID, V_PREV_SLOT_NO, 0, SUBLOT.TRAN_TIME, 'DETACH', V_PREV_CRR_HIST_SEQ, 0, 
                    SUBLOT.SUBLOT_ID, SUBLOT.HIST_SEQ, 0, ' ', 0, SUBLOT.TRAN_USER_ID);

                    SUBLOT.CRR_ID, SUBLOT.SLOT_NO, 0, SUBLOT.TRAN_TIME, 'ATTACH', V_CRR_HIST_SEQ, 0, 
                    SUBLOT.SUBLOT_ID, SUBLOT.HIST_SEQ, 0, ' ', 0, SUBLOT.TRAN_USER_ID);

            END IF;
            
        ELSIF SUBLOT.CRR_ID != ' ' THEN
        
            IF V_PREV_SLOT_NO != SUBLOT.SLOT_NO THEN

                    V_PREV_CRR_ID, V_PREV_SLOT_NO, 0, SUBLOT.TRAN_TIME, 'DETACH', V_CRR_HIST_SEQ, 0, 
                    SUBLOT.SUBLOT_ID, SUBLOT.HIST_SEQ, 0, ' ', 0, SUBLOT.TRAN_USER_ID);

                    SUBLOT.CRR_ID, SUBLOT.SLOT_NO, 0, SUBLOT.TRAN_TIME, 'CHANGE', V_CRR_HIST_SEQ, 0, 
                    SUBLOT.SUBLOT_ID, SUBLOT.HIST_SEQ, 0, ' ', 0, SUBLOT.TRAN_USER_ID);

                V_PREV_SLOT_NO := SUBLOT.SLOT_NO;
                
            END IF;
            
        END IF;

        V_PREV_CRR_ID := SUBLOT.CRR_ID;
        V_PREV_SLOT_NO := SUBLOT.SLOT_NO;
        V_PREV_CRR_HIST_SEQ := V_CRR_HIST_SEQ;

    END LOOP;
    
    V_PREV_CRR_ID := ' ';
    V_PREV_SLOT_NO := 0;
    V_OLD_SUBLOT_ID := ' ';
    V_OLD_CRR_HIST_SEQ := 0;
    V_OLD_SUBLOT_HIST_SEQ := 0;
    V_PREV_TRAN_CODE := ' ';

    FOR CRR_SLOT_HIST IN (
        SELECT * 
        FROM TRASCRRSHS 
        ORDER BY CRR_ID, SLOT_NO, TRAN_TIME, SUBLOT_HIST_SEQ
    )
    LOOP
    
        IF V_PREV_CRR_ID != CRR_SLOT_HIST.CRR_ID OR V_PREV_SLOT_NO != CRR_SLOT_HIST.SLOT_NO THEN
            V_PREV_CRR_ID := CRR_SLOT_HIST.CRR_ID;
            V_PREV_SLOT_NO := CRR_SLOT_HIST.SLOT_NO;

            V_OLD_SUBLOT_ID := ' ';
            V_OLD_CRR_HIST_SEQ := 0;
            V_OLD_SUBLOT_HIST_SEQ := 0;
            V_PREV_TRAN_CODE := ' ';
        END IF;
        
        V_SLOT_HIST_SEQ := 0;

        BEGIN
            SELECT /*+ INDEX_DESC(CSH MRASCRRSHS_PK ) */ HIST_SEQ
            INTO V_SLOT_HIST_SEQ
            FROM MRASCRRSHS CSH
            WHERE CRR_ID = CRR_SLOT_HIST.CRR_ID
                AND SLOT_NO = CRR_SLOT_HIST.SLOT_NO
                AND ROWNUM = 1;        
    
            EXCEPTION
            WHEN NO_DATA_FOUND THEN
                V_SLOT_HIST_SEQ := 0;
        END;
        
        V_SLOT_HIST_SEQ := V_SLOT_HIST_SEQ + 1;

        V_TRAN_CODE := CRR_SLOT_HIST.TRAN_CODE;
        
        IF V_PREV_TRAN_CODE = 'DETACH' AND CRR_SLOT_HIST.TRAN_CODE = 'CHANGE' THEN
            V_TRAN_CODE := 'ATTACH';
        END IF;

        IF V_TRAN_CODE = 'ATTACH' THEN
            V_OLD_SUBLOT_ID := ' ';
            V_OLD_SUBLOT_HIST_SEQ := 0;
        END IF;

        IF V_TRAN_CODE != 'DETACH' OR CRR_SLOT_HIST.SUBLOT_ID = V_OLD_SUBLOT_ID THEN
                CRR_SLOT_HIST.CRR_ID, CRR_SLOT_HIST.SLOT_NO, V_SLOT_HIST_SEQ, CRR_SLOT_HIST.TRAN_TIME, V_TRAN_CODE, CRR_SLOT_HIST.CRR_HIST_SEQ, 0, 
                CRR_SLOT_HIST.SUBLOT_ID, CRR_SLOT_HIST.SUBLOT_HIST_SEQ, V_OLD_CRR_HIST_SEQ, V_OLD_SUBLOT_ID, V_OLD_SUBLOT_HIST_SEQ, CRR_SLOT_HIST.TRAN_USER_ID);
        END IF;
        
        V_OLD_SUBLOT_ID := CRR_SLOT_HIST.SUBLOT_ID;
        V_OLD_SUBLOT_HIST_SEQ := CRR_SLOT_HIST.SUBLOT_HIST_SEQ;
        V_OLD_CRR_HIST_SEQ := CRR_SLOT_HIST.CRR_HIST_SEQ;
        V_PREV_TRAN_CODE := CRR_SLOT_HIST.TRAN_CODE;
    
    END LOOP;

    V_PREV_TRAN_TIME := '0';
    V_PREV_CRR_ID := ' ';
    V_PREV_CRR_HIST_SEQ := 0;

    FOR CRR_SLOT_HIST IN (
        SELECT * 
        FROM MRASCRRSHS 
        ORDER BY CRR_ID, TRAN_TIME, SLOT_NO
    )
    LOOP
    
        IF (TO_NUMBER(CRR_SLOT_HIST.TRAN_TIME) - TO_NUMBER(V_PREV_TRAN_TIME) > 2) OR
           (V_PREV_CRR_ID != CRR_SLOT_HIST.CRR_ID) OR
           (V_PREV_CRR_HIST_SEQ != CRR_SLOT_HIST.CRR_HIST_SEQ) THEN

            BEGIN    
                SELECT /*+ INDEX_DESC(CSH MRASCRRSHS_IDX_1 ) */ CRR_SLOT_HIST_SEQ
                INTO V_CRR_SLOT_HIST_SEQ
                FROM MRASCRRSHS CSH
                WHERE CRR_ID = CRR_SLOT_HIST.CRR_ID
                    AND ROWNUM = 1;
    
                EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    V_CRR_SLOT_HIST_SEQ := 0;
            END;
            
            V_CRR_SLOT_HIST_SEQ := V_CRR_SLOT_HIST_SEQ + 1;
            V_PREV_TRAN_TIME := CRR_SLOT_HIST.TRAN_TIME;

        END IF;
        
        UPDATE MRASCRRSHS 
        SET CRR_SLOT_HIST_SEQ = V_CRR_SLOT_HIST_SEQ 
        WHERE CRR_ID = CRR_SLOT_HIST.CRR_ID
            AND SLOT_NO = CRR_SLOT_HIST.SLOT_NO
            AND HIST_SEQ = CRR_SLOT_HIST.HIST_SEQ;

        V_PREV_CRR_ID := CRR_SLOT_HIST.CRR_ID;
        V_PREV_CRR_HIST_SEQ := CRR_SLOT_HIST.CRR_HIST_SEQ;
    
    END LOOP;

END;
/
DROP TABLE TRASCRRSHS PURGE;

