    CMF_8                       VARCHAR2(30)     DEFAULT(' ')    NOT NULL,
    CMF_9                       VARCHAR2(30)     DEFAULT(' ')    NOT NULL,
    CMF_10                      VARCHAR2(30)     DEFAULT(' ')    NOT NULL,
    CMF_11                      VARCHAR2(30)     DEFAULT(' ')    NOT NULL,  /* Add For V42 */
    CMF_12                      VARCHAR2(30)     DEFAULT(' ')    NOT NULL,  /* Add For V42 */
