DECLARE
    V_CNT	NUMBER(6);
BEGIN
  V_CNT := 0; 
	FOR REC IN (
		SELECT * FROM MGCMTBLDAT
		WHERE TABLE_NAME = 'GLOBAL_OPTION'
		) 
	LOOP

    IF REC.KEY_1 = 'AlarmInherit' THEN
      BEGIN
        UPDATE MBASGLBDEF SET VALUE_1 = REC.DATA_1 WHERE FACTORY = REC.FACTORY AND OPTION_NAME = 'MP_InheritAlarmToChild';
      EXCEPTION WHEN NO_DATA_FOUND THEN
        V_CNT := V_CNT + 1;
      END;
    ELSIF REC.KEY_1 = 'AllowCMFToTransact' THEN
      BEGIN
        UPDATE MBASGLBDEF SET VALUE_1 = REC.DATA_1 WHERE FACTORY = REC.FACTORY AND OPTION_NAME = 'MP_MakeHistoryCMFChange';
      EXCEPTION WHEN NO_DATA_FOUND THEN
        V_CNT := V_CNT + 1;
      END;
    ELSIF REC.KEY_1 = 'CarrierUsageCountPoint' THEN
      BEGIN
        UPDATE MBASGLBDEF SET VALUE_1 = REC.DATA_1 WHERE FACTORY = REC.FACTORY AND OPTION_NAME = 'MP_CarrierUsageCountPoint';
      EXCEPTION WHEN NO_DATA_FOUND THEN
        V_CNT := V_CNT + 1;
      END;
    ELSIF REC.KEY_1 = 'CarrierUsageIncreaseCount' THEN
      BEGIN
        UPDATE MBASGLBDEF SET VALUE_1 = REC.DATA_1 WHERE FACTORY = REC.FACTORY AND OPTION_NAME = 'MP_CarrierUsageIncreaseCount';
      EXCEPTION WHEN NO_DATA_FOUND THEN
        V_CNT := V_CNT + 1;
      END;
    ELSIF REC.KEY_1 = 'CycleTimeUnit(H/M)' THEN
      BEGIN
        UPDATE MBASGLBDEF SET VALUE_1 = REC.DATA_1 WHERE FACTORY = REC.FACTORY AND OPTION_NAME = 'MP_CycleTimeUnit';
