BEGIN
	FOR REC IN (
		SELECT DISTINCT FACTORY FROM MWIPFACDEF
		MINUS
		SELECT DISTINCT FACTORY FROM MGCMTBLDAT 
		WHERE TABLE_NAME = 'CMF_ITEM_NAME'
		    AND KEY_1 = 'CMF_SERVICE'
