values ('LOGLEVEL','Level of the log saved in the log file (0 = Save all the logs of Error, Warning, Information, Debug, 1 = Save all the logs of Error, Warning, Information, 2 = Save only the log at Error, Warning, 3 = Save only the log at Error)',' ',' ','Char',0,' ',' ',0,0,'ADMIN','200812010101','ADMIN','20091216172400');

update MSVMSVCMBR set member_path = 'CHG_LOGLEVEL', member_name = 'CHG_LOGLEVEL', member_prt = 'CHG_LOGLEVEL' 
where module_name = 'ADM' and service_name = 'ADM_Change_EnvValues' and direction = 'I' and member_path = 'LOGLEVEL';

BEGIN
    FOR SERVICE IN (
        SELECT DISTINCT MODULE_NAME, SERVICE_NAME 
        FROM MSVMSVCMBR 
        WHERE MEMBER_PATH = 'PASSPORT'
          AND DIRECTION = 'I'
        ORDER BY MODULE_NAME, SERVICE_NAME
    )
    LOOP
        BEGIN
              values (SERVICE.MODULE_NAME,SERVICE.SERVICE_NAME,'I','LOGLEVEL',0,1,' ','LOGLEVEL','LOGLEVEL',' ',' ','Char',1,'LOGLEVEL',' ','O',' ',' ',0,0,'ADMIN','20091216165201',' ',' ');
            EXCEPTION when OTHERS THEN
              NULL;
        END;
    END LOOP;
END;
